"use strict";
const play_btt = document.querySelector('.playBTT');
const display = document.querySelector('.display');
const message = document.querySelector('.message');
const pointDP = document.querySelector('.point');
const statsDP = document.querySelector('.statsDP');
function Generator(min, max) {
    const minCeiled = Math.ceil(min);
    const maxFloored = Math.floor(max);
    return Math.floor(Math.random() * (maxFloored - minCeiled + 1) + minCeiled);
}
let games = 0;
let wins = 0;
let losses = 0;
function UpdateStats() {
    statsDP.innerText = "Wins: " + wins + " Losses: " + losses + " Proportion: " + (wins / games).toFixed(2);
}
let point = 0;
function Play() {
    console.log("working");
    let current = (Generator(1, 6) + Generator(1, 6));
    display.innerText = "Roll: " + String(current);
    if (point == 0) {
        if (current == 7 || current == 11) {
            //console.log("win");
            message.innerText = "You win";
            wins++;
            games++;
            UpdateStats();
            return;
        }
        else if (current == 2 || current == 3 || current == 12) {
            //console.log('lost');
            message.innerText = "You lose";
            losses++;
            games++;
            UpdateStats();
            return;
        }
        point = current;
        //let active: boolean = true;
        pointDP.innerText = "Point: " + String(point);
        message.innerText = "New point set";
        return;
    }
    if (current == 7) {
        message.innerText = "You lose";
        point = 0;
        pointDP.innerText = "";
        losses++;
        games++;
        UpdateStats();
        return;
    }
    else if (current != point && point != 7) {
        message.innerText = "Roll is not point";
        //UpdateStats();
        return;
    }
    else {
        message.innerText = "You win";
        point = 0;
        pointDP.innerText = "";
        wins++;
        games++;
        UpdateStats();
        return;
    }
}
